// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RevenueWorkspace) predicate.RevenueWorkspace {
	return predicate.RevenueWorkspace(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RevenueWorkspace) predicate.RevenueWorkspace {
	return predicate.RevenueWorkspace(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RevenueWorkspace) predicate.RevenueWorkspace {
	return predicate.RevenueWorkspace(sql.NotPredicates(p))
}
